const results = [];

for (const item of $input.all()) {
  const recipe = item.json;
  const sentences = recipe.instructions
    .split(/(?<=[.!?])\s+/)
    .filter(s => s.trim().length > 0);

  const chunkSize = 2;
  for (let i = 0; i < sentences.length; i += chunkSize) {
    results.push({
      json: {
        recipeName: recipe.name,
        category: recipe.category,
        ingredients: recipe.ingredients,
        chunkIndex: Math.floor(i / chunkSize),
        chunkText: sentences.slice(i, i + chunkSize).join(' ')
      }
    });
  }
}

return results;

const items = $input.all();
return items.map((item, i) => {
  const chunkData = $('Chunk Fremgangsmåde').itemMatching(i).json;
  return {
    json: {
      recipeName: chunkData.recipeName,
      category: chunkData.category,
      ingredients: chunkData.ingredients,
      chunkIndex: chunkData.chunkIndex,
      chunkText: chunkData.chunkText,
      embedding: item.json.embeddings[0]
    }
  };
});

