={
  "statement": "MERGE (r:Recipe {name: $recipeName}) WITH r UNWIND split($category, ', ') AS catName MERGE (c:Category {name: catName}) MERGE (r)-[:BELONGS_TO]->(c) WITH DISTINCT r UNWIND split($ingredients, ', ') AS ingName MERGE (i:Ingredient {name: ingName}) MERGE (r)-[:CONTAINS]->(i) WITH DISTINCT r MERGE (ch:Chunk {recipeName: $recipeName, chunkIndex: $chunkIndex}) SET ch.text = $chunkText, ch.embedding = $embedding MERGE (r)-[:HAS_CHUNK]->(ch) RETURN r.name AS recipe, ch.chunkIndex AS chunk",
  "parameters": {
    "recipeName": "{{ $json.recipeName }}",
    "category": "{{ $json.category }}",
    "ingredients": "{{ $json.ingredients }}",
    "chunkIndex": {{ $json.chunkIndex }},
    "chunkText": "{{ $json.chunkText }}",
    "embedding": {{ JSON.stringify($json.embedding) }}
  }
}

